import pathlib,json,hashlib,importlib.util,collections,numpy as np,gzip,zipfile,csv,io
R=pathlib.Path(r'C:\tmp\disdex-d126-crossrunner-research-20261126');B=R/'Y06_BINANCE_PUBLIC_1H_20261127'
SRC=R/'y06_r3_bear_retest_research_v2.py'
sp=importlib.util.spec_from_file_location('r3',SRC);r3=importlib.util.module_from_spec(sp);sp.loader.exec_module(r3)
bt=r3.bt;H=bt.H;M=bt.M
P=R/'Y06_R15_BINANCE_NORMALIZED_PROTOCOL_20261127.json';O=R/'Y06_R15_BINANCE_NORMALIZED_RESULTS_20261127.json'
assert not P.exists() and not O.exists()
p={'status':'RESEARCH_ONLY_NO_LIVE','source_sha256':hashlib.sha256(SRC.read_bytes()).hexdigest(),'binance_manifests':{f:hashlib.sha256((B/f).read_bytes()).hexdigest() for f in ('manifest.json','daily_manifest.json')},'signal':'At each 3h UTC boundary, completed previous 24h H1 kline, actual taker buy share. 3h signed taker imbalance opposite 3h price return, abs imbalance>=.15, recent3h volume vs prior21h >=1.5; direction of price, SHORT only. Source independent. Binance and ASTER separate volume scales; not merged. Highest abs imbalance*volume ratio among eligible symbols per arm. ASTER tradability only uses original R3 causal QA.','arms':['ASTER','BINANCE','BOTH','BINANCE_ASTER_PRICE','BINANCE_ASTER_NOT_BULL','BINANCE_ASTER_LAG','BINANCE_M5','BINANCE_M15','BINANCE_H1','BOTH_M5','ASTER_H1'],'definitions':'BOTH both venues independently detect absorption same symbol/side at same time; PRICE ASTER prior3h down; NOT_BULL ASTER BTC3h<=0; LAG Binance3h return below ASTER3h by >=0.5 percentage points; M5/M15/H1 wait first closed candle below origin open and bearish, max3h, original QA rechecked at most recent completed H1 plus preceding 48h M5 nonzero ratio>=.75. No re-ranking after confirmation.','exits':'H24/H48 fixed and TP8 at each horizon, STOP8 conservative same-bar stop first; adverse gap; gross .30 2 slots, 12h cooldown, 10/30bps. Fixed boundary exclusions before replay. Funding sensitivity TARGET only if all rates archived, actual signed funding based on M5 mark proxy; funding cashflows included chronologically in equity, entry and exit boundary events excluded with explicit count.','controls':'32 same-timestamp alternative-symbol placebo for every fixed H48 arm with >=2 positive periods and BINANCE/H24, BINANCE/H48, BOTH/H48, ASTER/H48. Exact side and exit. Controls match QA not signal; for delayed entries use same delayed timestamp. No independent periods.','limits':'Data Binance archive monthly through Oct2026, daily through Nov25; 26 daily absent outside entry period. No OI/board/liq in this run. All periods previously inspected.'}
p.update({'parent_sha256':hashlib.sha256((R/'Y06_R14_BINANCE_CROSS_VENUE_RESULTS_20261127.json').read_bytes()).hexdigest(),'signal':'Binance rolling z-score of signed 3h taker imbalance vs previous 30d disjoint 3h buckets, strictly excludes current bucket, min60 observations. Absorption SHORT when positive imbalance, z>=1 and price falls, volume ratio>=1.2; strict z>=1.5 and ratio>=1.5. Continuation SHORT when imbalance<0,z<=-1, price falls, ratio>=1.2. ASTER original fixed 15% absorption comparator. Each arm separately ranks candidates by its own score. All initial gates predeclared after R14, exploratory.','arms':['ASTER','ASTER_H1','BINANCE_NORM','BINANCE_STRICT','BINANCE_CONT','BOTH_NORM','ASTER_BINANCE_NOT_BULL','ASTER_BINANCE_CONT','BINANCE_ASTER_PRICE','BINANCE_ASTER_LAG','BINANCE_NORM_M5','BINANCE_NORM_M15','BINANCE_NORM_H1','BINANCE_CONT_M5','BOTH_NORM_M5'],'definitions':'BOTH_NORM both venues absorption; ASTER_BINANCE_NOT_BULL ASTER absorption and Binance price3h<=0; ASTER_BINANCE_CONT ASTER absorption plus Binance continuation; BINANCE_ASTER_PRICE normalized Binance absorption plus ASTER price3h negative; LAG normalized Binance absorption price3h <= ASTER return3h minus0.5pp. Confirmation same R14 causal QA.','controls':'32 same-time other-symbol controls on all fixed H48 variants with >=2 positive splits, plus BINANCE_NORM/24, BINANCE_NORM/48, BINANCE_CONT/48, ASTER/48 and ASTER_H1/48.','funding':'Same TARGET funding proxy as R14. Missing rate coverage independently reviewed.'})
P.write_text(json.dumps(p,indent=2),encoding='utf8')
btc,_=bt.data('BTC','1h');hs={};ms={};qa={};af={};bf={};bh={};fund={}
def a_flow(sym):
 out=np.full((len(btc),3),np.nan)
 for folder,part in bt.HFiles+[(None,'fresh')]:
  path=bt.ROOT/folder/(sym+'USDT-'+part+'.jsonl.gz') if folder else bt.FEED/bt.mf['candle_counts'][sym+'USDT_1h']['filename']
  with gzip.open(path,'rt',encoding='utf8') as f:
   for line in f:
    a=json.loads(line);t=int(a[0]);i=(t-bt.HS)//H
    if not(0<=i<len(out)) or (t-bt.HS)%H:continue
    try:v,b,n=float(a[5]),float(a[9]),float(a[8])
    except (ValueError,IndexError,TypeError):continue
    if np.isfinite([v,b,n]).all() and 0<=b<=v+1e-9 and n>=0:out[i]=[v,min(b,v),n]
 return out
def b_data(sym):
 out=np.full((len(btc),6),np.nan);dups=bad=0
 for f in sorted(B.glob(sym+'USDT-1h-*.zip')):
  with zipfile.ZipFile(f) as z:
   with z.open(z.namelist()[0]) as raw:
    for row in csv.reader(io.TextIOWrapper(raw,encoding='utf-8-sig')):
     try:t=int(row[0]);i=(t-bt.HS)//H;v=np.array([float(row[j]) for j in (1,2,3,4,5,9)])
     except (ValueError,IndexError):continue
     if not(0<=i<len(out)) or (t-bt.HS)%H:continue
     if not np.isfinite(v).all() or min(v[:4])<=0 or v[1]<max(v[0],v[3]) or v[2]>min(v[0],v[3]) or not 0<=v[5]<=v[4]+1e-9:bad+=1;continue
     if np.isfinite(out[i]).all():
      dups+=1
      if not np.allclose(out[i],v,rtol=1e-8,atol=1e-9):raise ValueError('conflicting Binance duplicate')
     out[i]=v
 return out,{'valid':int(np.isfinite(out[:,3]).sum()),'duplicate':dups,'invalid':bad}
coverage={}
for sym in bt.SYMS:
 h,_=bt.data(sym,'1h');bh[sym],coverage[sym]=b_data(sym)
 if sym!='BTC':
  m,_=bt.data(sym,'5m');hs[sym]=h;ms[sym]=m;qa[sym]=r3.prepare_qa(h,m)[0];af[sym]=a_flow(sym)
  f=bt.ROOT/'aster-public-funding'/(sym+'USDT-20251001-20261001.json')
  if f.exists():
   rows=json.loads(f.read_text(encoding='utf8'));fund[sym]=sorted((int(x['fundingTime']),float(x['fundingRate'])) for x in rows)
 print('LOAD',sym,coverage[sym],flush=True)
def perof(t):return next((k for k,(a,b) in bt.PERIODS.items() if a<=t<b),None)
def endof(per):return bt.PERIODS[per][1] if per!='FORWARD_INSPECTED' else bt.T('2026-11-26T00:00:00Z')
def flow(h,v,b,i):
 if i<25 or not np.isfinite(h[i-25:i,3]).all() or not np.isfinite(v[i-24:i]).all() or not np.isfinite(b[i-24:i]).all():return None
 vv=v[i-24:i];bb=b[i-24:i]
 if vv[-3:].sum()<=0 or vv[:-3].sum()<=0:return None
 im=float(2*bb[-3:].sum()/vv[-3:].sum()-1);ratio=float(vv[-3:].mean()/vv[:-3].mean());ret=float(h[i-1,3]/h[i-4,3]-1)
 return (im,ratio,ret)
def isabs(f):return f is not None and f[0]>=.15 and f[1]>=1.5 and f[2]<0
def confirms(x,step):
 m=ms[x['symbol']];k=(x['entryTs']-bt.MS)//M
 if k<0 or k>=len(m) or not np.isfinite(m[k,0]):return None
 ep=m[k,0]
 for j in range(k+step,min(k+36,len(m)-1)+1,step):
  t=bt.MS+j*M;i=(t-bt.HS)//H
  if t>=bt.PERIODS[x['period']][1] or not np.isfinite(m[j-step:j,:4]).all():break
  if not qa[x['symbol']][i] or j<576 or not np.isfinite(m[j-576:j,:4]).all() or np.mean(m[j-576:j,4]>0)<.75:continue
  if m[j-1,3]<ep and m[j-1,3]<m[j-step,0]:return {**x,'entryTs':t,'originTs':x['entryTs']}
 return None
norm={}
for sym,bb in bh.items():
 im=np.full(len(bb),np.nan);z=np.full(len(bb),np.nan)
 for i in range(3,len(bb),3):
  v=bb[i-3:i,4];b=bb[i-3:i,5]
  if np.isfinite(v).all() and np.isfinite(b).all() and v.sum()>0:im[i]=2*b.sum()/v.sum()-1
  a=im[max(0,i-720):i:3];a=a[np.isfinite(a)]
  if len(a)>=60 and np.isfinite(im[i]) and np.std(a)>1e-9:z[i]=(im[i]-a.mean())/a.std()
 norm[sym]=z
tapes={a:[] for a in p['arms']};avail=collections.defaultdict(collections.Counter);eligible={}
for i in range(220,len(btc)):
 t=bt.HS+i*H;per=perof(t)
 if not per or t%(3*H):continue
 c=avail[per];c['snapshots']+=1;options=collections.defaultdict(list);sy=[]
 for sym,h in hs.items():
  if not qa[sym][i] or not np.isfinite(h[i-73:i,:5]).all():continue
  av=af[sym];bb=bh[sym];a=flow(h,av[:,0],av[:,1],i);b=flow(bb,bb[:,4],bb[:,5],i)
  if a is None or b is None:continue
  if not np.allclose(av[i-24:i,0],h[i-24:i,4],rtol=1e-6,atol=1e-6):continue
  sy.append(sym);c['paired_asset_observations']+=1
  x=dict(symbol=sym,period=per,entryTs=t,aster_flow=a,binance_flow=b)
  if isabs(a):options['ASTER'].append((a[0]*min(a[1],10),x));c['aster_signals']+=1
  z=norm[sym][i]
  if not np.isfinite(z):continue
  x['binance_z']=float(z)
  bs=b[0]>0 and z>=1 and b[1]>=1.2 and b[2]<0
  bc=b[0]<0 and z<=-1 and b[1]>=1.2 and b[2]<0
  if isabs(a) and b[2]<=0:options['ASTER_BINANCE_NOT_BULL'].append((a[0]*min(a[1],10),x))
  if bc:
   score=-z*min(b[1],10);options['BINANCE_CONT'].append((score,x));c['binance_cont_signals']+=1
   if isabs(a):options['ASTER_BINANCE_CONT'].append((score,x))
  if bs:
   c['binance_norm_signals']+=1;score=z*min(b[1],10)
   options['BINANCE_NORM'].append((score,x))
   if z>=1.5 and b[1]>=1.5:options['BINANCE_STRICT'].append((score,x))
   if isabs(a):options['BOTH_NORM'].append((score,x));c['both_norm_signals']+=1
   if a[2]<0:options['BINANCE_ASTER_PRICE'].append((score,x))
   if b[2]<=a[2]-.005:options['BINANCE_ASTER_LAG'].append((score,x))
 eligible[t]=sy
 for arm,items in options.items():
  score,x=max(items,key=lambda z:(z[0],z[1]['symbol']));tapes[arm].append(x)
  for base,derived,step in [('BINANCE_NORM','BINANCE_NORM_M5',1),('BINANCE_NORM','BINANCE_NORM_M15',3),('BINANCE_NORM','BINANCE_NORM_H1',12),('BINANCE_CONT','BINANCE_CONT_M5',1),('BOTH_NORM','BOTH_NORM_M5',1),('ASTER','ASTER_H1',12)]:
   if arm==base:
    z=confirms(x,step)
    if z:tapes[derived].append(z)
for per,v in avail.items():print('COVERAGE',per,dict(v),flush=True)
def trade(x,hr,tp):
 m=ms[x['symbol']];k=(x['entryTs']-bt.MS)//M;j=k+hr*12
 if x['entryTs']+hr*H>=endof(x['period']) or k<0 or j>=len(m) or not np.isfinite(m[k:j+1,:4]).all():return None
 ep=float(m[k,0]);stop=ep*1.08;target=ep*(1-tp) if tp else None
 sh=np.flatnonzero(m[k:j,1]>=stop);th=np.flatnonzero(m[k:j,2]<=target) if tp else []
 si=int(sh[0]) if len(sh) else j-k;ti=int(th[0]) if len(th) else j-k
 xp=float(m[j,0]);et=bt.MS+j*M;reason='TIME'+str(hr)
 if si<=ti and si<j-k:q=k+si;xp=float(max(m[q,0],stop));et=bt.MS+(q+1)*M;reason='HARD_STOP8'
 elif ti<j-k:xp=float(target);et=bt.MS+(k+ti+1)*M;reason='TARGET'
 return {**x,'entry':ep,'exitPrice':xp,'exitTs':et,'direction':'SHORT','rawReturn':1-xp/ep,'exitReason':reason}
def compact(w):return {k:v for k,v in w.items() if k!='accepted'}
# Funding sensitivity: original wallet logic with cashflows applied at next M5 index using current mark.
def fw_wallet(cands,fee):
 begin,end=bt.PERIODS['TARGET'];eq=np.full((end-begin)//M+1,10000.);active=[];cool={};accepted=[];missing=0;events=0;fund_jpy=0.;boundary=0
 for x in sorted(cands,key=lambda y:(y['entryTs'],y['symbol'])):
  t=x['entryTs'];e=x['exitTs'];sym=x['symbol'];active=[a for a in active if a['exitTs']>t]
  if e>=end or len(active)>=2 or any(a['symbol']==sym for a in active) or t<cool.get(sym,0):continue
  if sym not in fund:missing+=1;continue
  i=(t-begin)//M;j=(e-begin)//M;s=(t-bt.MS)//M;notional=.30*eq[i];m=ms[sym];prices=m[s:s+j-i,0]
  if len(prices)!=j-i or not np.isfinite(prices).all():missing+=1;continue
  ff=[]
  for ft,rate in fund[sym]:
   if ft==t or ft==e:boundary+=1
   if not(t<ft<e):continue
   z=(ft-begin+M-1)//M;mi=(ft-bt.MS+M-1)//M
   if mi>=len(m) or not np.isfinite(m[mi,0]):ff=None;break
   ff.append((z,notional*float(m[mi,0])/x['entry']*rate))
  if ff is None:missing+=1;continue
  eq[i:j]+=notional*(1-prices/x['entry']-fee/20000)
  net=notional*(x['rawReturn']-fee/10000);eq[j:]+=net
  fsum=sum(v for z,v in ff)
  for z,v in ff:eq[z:]+=v
  events+=len(ff);fund_jpy+=fsum;accepted.append(net+fsum);active.append(x);cool[sym]=e+12*H
 peak=np.maximum.accumulate(np.r_[10000,eq])[1:]
 return {'terminal_jpy':float(eq[-1]),'max_dd_pct':float(100*np.max(1-eq/peak)),'n':len(accepted),'wins':sum(v>0 for v in accepted),'funding_jpy':float(fund_jpy),'funding_events':events,'missing':missing,'boundary_excluded_events':boundary}
out={};full={}
for arm,xs in tapes.items():
 xs=list({(x['symbol'],x['entryTs']):x for x in xs}.values())
 for hr,tp in [(24,0),(48,0),(24,.08),(48,.08)]:
  key=arm+'/'+str(hr)+('_TP8' if tp else '');out[key]={};full[key]={}
  for per in bt.PERIODS:
   a=[x for x in xs if x['period']==per and x['entryTs']+hr*H<endof(per)]
   z=[q for x in a if (q:=trade(x,hr,tp)) is not None];full[key][per]=z
   w={str(f):compact(bt.wallet(z,per,f,ms)) for f in (10,30)}
   out[key][per]={'intentions':len(a),'unpriced':len(a)-len(z),'wallet':w}
   if per=='TARGET':out[key][per]['funding_proxy30']=fw_wallet(z,30)
  print('BT',key,[(round(v['wallet']['30']['terminal_jpy']),round(v['wallet']['30']['max_dd_pct'],2),v['wallet']['30']['n'],v['wallet']['30']['wins'],round(v['wallet']['10']['terminal_jpy'])) for v in out[key].values()],flush=True)
rng=np.random.default_rng(2026112714)
for key,rs in out.items():
 arm,ex=key.split('/');hr=int(ex.split('_')[0]);tp=.08 if 'TP8' in ex else 0
 if not(key in ('BINANCE_NORM/24','BINANCE_NORM/48','BINANCE_CONT/48','ASTER/48','ASTER_H1/48') or (hr==48 and sum(v['wallet']['30']['terminal_jpy']>10000 for v in rs.values())>=2)):continue
 for per,rec in rs.items():
  pairs=[]
  for x in full[key][per]:
   t=x['entryTs'];i=(t-bt.HS)//H
   aa=[q for s,h in hs.items() if s!=x['symbol'] and qa[s][i] and np.isfinite(h[i-73:i,:5]).all() and np.isfinite(bh[s][i-24:i,:]).all() and (q:=trade({**x,'symbol':s},hr,tp)) is not None]
   if len(aa)>=2:pairs.append((x,aa))
  aw=compact(bt.wallet([x for x,a in pairs],per,30,ms));ds=[compact(bt.wallet([a[rng.integers(len(a))] for x,a in pairs],per,30,ms)) for _ in range(32)];vals=[d['terminal_jpy'] for d in ds]
  rec['matched']={'n_pairs':len(pairs),'actual':aw,'mean_terminal':float(np.mean(vals)),'beats':sum(aw['terminal_jpy']>v for v in vals),'delta_pp':float(np.mean([100*(x['rawReturn']-np.mean([z['rawReturn'] for z in a])) for x,a in pairs])) if pairs else None,'draws':ds}
  print('MATCH',key,per,len(pairs),round(aw['terminal_jpy']),round(np.mean(vals)),rec['matched']['beats'],rec['matched']['delta_pp'],flush=True)
O.write_text(json.dumps({'protocol':p,'protocol_sha256':hashlib.sha256(P.read_bytes()).hexdigest(),'coverage':coverage,'signal_coverage':{k:dict(v) for k,v in avail.items()},'results':out,'tapes':tapes},indent=2,allow_nan=False,default=lambda x:x.item()),encoding='utf8')
print('SAVED',hashlib.sha256(O.read_bytes()).hexdigest(),flush=True)
